const records = $ctrl.countryData.countries || [];
$ctrl.continentOptions = [{ label: 'All continents', value: 'all' }].concat(($ctrl.countryData.continents || []).map(c => ({ label: c.name, value: c.code })));
if ($ctrl.countryData.lastUpdated != null) {
  const continents = new Set(records.map(c => c.continentCode).filter(Boolean));
  const languages = new Set(records.flatMap(c => Array.isArray(c.languages) ? c.languages : []).filter(name => typeof name === 'string' && name.trim()).map(name => name.trim()));
  $ctrl.metrics = { countries: String(records.length), continents: String(continents.size), languages: String(languages.size) };
} else {
  $ctrl.metrics = { countries: '—', continents: '—', languages: '—' };
}
$ctrl.applyFilters(false);

if ($ctrl.loading) { return; }
$ctrl.loading = true;
$ctrl.loadError = null;
// The service owns network access, shared in-flight work, and caching.
return $ctrl.$q.when().then(() => $ctrl.countryData.loadCountries(force === true)).then(() => {
  $ctrl.syncData();
}).catch(() => {
  $ctrl.loadError = 'Unable to load country data. Please try again. Previously loaded data, if available, is still shown.';
}).finally(() => {
  $ctrl.loading = false;
});

const query = String($ctrl.searchQuery || '').trim().toLocaleLowerCase();
const records = $ctrl.countryData.countries || [];
$ctrl.filteredCountries = records.filter(c => ($ctrl.continent === 'all' || c.continentCode === $ctrl.continent) && (!query || [c.name, c.native, c.code, c.capital].some(value => String(value || '').toLocaleLowerCase().includes(query)))).slice().sort((a, b) => {
  const order = a.name.localeCompare(b.name) || a.code.localeCompare(b.code);
  return $ctrl.sortOrder === 'desc' ? -order : order;
});
$ctrl.totalPages = Math.max(1, Math.ceil($ctrl.filteredCountries.length / 12));
$ctrl.changePage(resetPage ? 1 : $ctrl.currentPage);

$ctrl.currentPage = Math.max(1, Math.min($ctrl.totalPages, Math.floor(Number(currentPage) || 1)));
const count = $ctrl.filteredCountries.length;
const start = ($ctrl.currentPage - 1) * 12;
$ctrl.pageCountries = $ctrl.filteredCountries.slice(start, start + 12);
$ctrl.resultSummary = count ? 'Showing ' + (start + 1) + '–' + Math.min(start + 12, count) + ' of ' + count + ' countries' : '0 countries match your filters';

if (!country) { return; }
$ctrl.returnFocus = $ctrl.$window.document.activeElement;
$ctrl.selectedCountry = country;
const phone = country.phone ? String(country.phone).split(',').map(code => '+' + code.trim().replace(/^\+/, '')).join(', ') : '—';
$ctrl.detailFields = [
  { label: 'Name', value: country.name || '—' },
  { label: 'Native name', value: country.native || '—' },
  { label: 'Capital', value: country.capital || '—' },
  { label: 'Currency', value: country.currency || '—' },
  { label: 'Calling code', value: phone },
  { label: 'Languages', value: country.languages && country.languages.length ? country.languages.join(', ') : '—' },
  { label: 'Continent', value: country.continentName || '—' },
  { label: 'ISO code', value: country.code || '—' }
];
$ctrl.$timeout(() => {
  const heading = $ctrl.$window.document.getElementById('pw-country-detail-heading');
  if (heading) { heading.focus(); }
}, 0);

$ctrl.selectedCountry = null;
$ctrl.$timeout(() => {
  const document = $ctrl.$window.document;
  const target = $ctrl.returnFocus && document.contains($ctrl.returnFocus) ? $ctrl.returnFocus : document.getElementById('pw-countries-results');
  if (target) { target.focus(); }
  $ctrl.returnFocus = null;
}, 0);
